import{_ as e,o as a,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/start/overview-documents-list.png",m=JSON.parse('{"title":"Wafflebase","description":"Wafflebase is a collaborative office suite for sheets, documents, presentations, notes, and boards that your team edits together in the browser.","frontmatter":{"title":"Wafflebase","description":"Wafflebase is a collaborative office suite for sheets, documents, presentations, notes, and boards that your team edits together in the browser.","type":"overview"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function d(i,t,h,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="wafflebase" tabindex="-1">Wafflebase <a class="header-anchor" href="#wafflebase" aria-label="Permalink to &quot;Wafflebase&quot;">​</a></h1><p>Wafflebase is a collaborative office suite for sheets, documents, presentations, notes, and boards that your team edits together in the browser.</p><p>Use it to:</p><ul><li>Build spreadsheets, write documents, and present slides without installing anything</li><li>Edit the same document at the same time as your team, and see who is working where</li><li>Share any document with a link, so people outside your workspace can view or edit it</li></ul><p><img src="'+r+'" alt="Workspace documents list with the sidebar and the New menu open"></p><h2 id="get-started-in-3-steps" tabindex="-1">Get started in 3 steps <a class="header-anchor" href="#get-started-in-3-steps" aria-label="Permalink to &quot;Get started in 3 steps&quot;">​</a></h2><ol><li><strong>Create a document.</strong> Sign in, click <strong>New</strong> above your documents list, and pick a type. See <a href="/docs/start/getting-started.html">Getting started</a>.</li><li><strong>Edit it.</strong> Changes save as you type. The header shows <strong>Saved</strong> once they reach the server.</li><li><strong>Share it.</strong> Click <strong>Share</strong> in the top right of the editor, then <strong>Create link</strong>. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><h2 id="learn-the-basics" tabindex="-1">Learn the basics <a class="header-anchor" href="#learn-the-basics" aria-label="Permalink to &quot;Learn the basics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Read</th></tr></thead><tbody><tr><td>Sign in, build a first sheet, share it, and edit it with someone</td><td><a href="/docs/start/getting-started.html">Getting started</a></td></tr><tr><td>Understand workspaces, documents, folders, share links, and templates</td><td><a href="/docs/start/concepts.html">Concepts</a></td></tr><tr><td>Find out what works on a phone and where the controls move</td><td><a href="/docs/start/phone.html">Use Wafflebase on a phone</a></td></tr><tr><td>Install the app for Mac or Windows and connect it to your server</td><td><a href="/docs/start/desktop.html">Use the desktop app</a></td></tr><tr><td>Fix a sign-in, saving, or share link problem</td><td><a href="/docs/start/troubleshooting.html">Troubleshooting</a></td></tr></tbody></table><h2 id="choose-an-editor" tabindex="-1">Choose an editor <a class="header-anchor" href="#choose-an-editor" aria-label="Permalink to &quot;Choose an editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Use it for</th><th>Create it with</th></tr></thead><tbody><tr><td><a href="/docs/sheets/">Sheets</a></td><td>Tables, formulas, charts, and pivot tables</td><td><strong>New &gt; New sheet</strong></td></tr><tr><td><a href="/docs/docs-editor/">Docs</a></td><td>Paged documents with rich text, tables, and images</td><td><strong>New &gt; New document</strong></td></tr><tr><td><a href="/docs/slides/">Slides</a></td><td>Presentations with themes, layouts, and animations</td><td><strong>New &gt; New presentation</strong></td></tr><tr><td><a href="/docs/notes/">Notes</a></td><td>Markdown notes with a live preview</td><td><strong>New &gt; New note</strong></td></tr><tr><td><a href="/docs/board/">Board</a></td><td>An infinite canvas for sticky notes, shapes, and drawing</td><td><strong>New &gt; New board</strong></td></tr><tr><td><a href="/docs/files/upload.html">Files</a></td><td>PDFs, images, and any other file you upload</td><td><strong>New &gt; Upload files…</strong></td></tr></tbody></table><p>To bring in existing work, use <strong>New &gt; Upload files…</strong> or drag files onto the documents list. A <code>.xlsx</code>, <code>.csv</code>, <code>.docx</code>, or <code>.pptx</code> file becomes an editable document. See <a href="/docs/files/import-export.html">Import and export</a>.</p><p>Inside a workspace, the <strong>New</strong> menu also has <strong>New from template</strong>, <strong>New folder</strong>, and <strong>Import from Miro…</strong>, which brings a Miro board in as a board.</p><h2 id="work-together" tabindex="-1">Work together <a class="header-anchor" href="#work-together" aria-label="Permalink to &quot;Work together&quot;">​</a></h2><ul><li><a href="/docs/collaborate/share.html">Share a document</a> with a viewer or editor link</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a> and see each other&#39;s cursors live</li><li><a href="/docs/collaborate/comments.html">Comment and mention people</a> in sheets, documents, boards, and PDFs</li><li><a href="/docs/collaborate/version-history.html">Restore an earlier version</a> from version history</li><li><a href="/docs/collaborate/templates.html">Start from a template</a>, or publish your own</li><li>Organize with <a href="/docs/collaborate/folders.html">folders</a>, and recover deleted documents from the <a href="/docs/collaborate/trash.html">Trash</a></li></ul><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Every editor opens on a phone. Comments, version history, and export move into the <strong>⋮</strong> (<strong>More</strong>) menu in the header. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/start/getting-started.html">Getting started</a>: build and share your first sheet in about 10 minutes</li><li><a href="/docs/start/concepts.html">Concepts</a>: learn who can see and change what</li><li><a href="/docs/developers/">Developers</a>: script Wafflebase with the CLI and REST API, or host it yourself</li></ul>',19)])])}const g=e(n,[["render",d]]);export{m as __pageData,g as default};
